def haifacity_dm_messages(me)
	name   = haifacity_display_name(me)
	recent = haifacity_group_msgs(15).map {|m| "#{m[:name]}: #{m[:text]}" }
	lang   = HAIFACITY_LANGS[haifacity_lang][:english]
	system = HAIFACITY_PERSONA + "\n" + HAIFACITY_ACTIONS_GUIDE + "\nThis is a private chat - only you and the user see it. The user's name is #{name}.\n"
	system += "The user picked #{lang} as their language: answer in #{lang}, unless they write to you in another language - then answer in theirs.\n"
	system += "\nFor context, the latest messages in the community's public group chat (the user may ask about them):\n#{recent.join("\n")}\n" if recent.any?
	history = haifacity_dm_history(me[:_id]).last(AI_MAX_CONTEXT_MSGS).map {|m| {role: m[:role].to_s, content: m[:text].to_s} }
	[{role: 'system', content: system}] + history
end

def haifacity_group_msgs(limit = HAIFACITY_GROUP_SHOWN)
	$haifacity_msgs.find({status: 'ok'}, sort: {created_at: -1}, limit: limit).to_a.reverse
end

